box=[polygon([[70,65],[215,65],[280,30],[135,30]]),polygon([[70,65],[215,65],[215,155],[70,155]]),polygon([[215,65],[280,30],[280,120],[215,155]]),line(70,155,135,120,True),line(135,120,280,120,True),line(135,120,135,30,True)]
