add('11-08-2',[ellipse(175,145,65,20),line(175,20,110,145),line(175,20,240,145),line(175,20,175,145,True),line(175,145,240,145),label('4 см',155,91),label('3 см',210,176),label('l = ?',241,78)],'Конус: радиус 3 см, высота 4 см, образующая неизвестна.')
