add('11-08-4',[ellipse(180,45,36,12),ellipse(180,145,83,22),line(144,45,97,145),line(216,45,263,145),line(180,45,216,45),line(180,145,263,145),line(180,45,180,145,True),label('2 см',206,29),label('5 см',227,177),label('3 см',158,103)],'Усечённый конус: радиусы оснований 2 и 5 см, высота 3 см.')
